const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=v=>structuredClone(v), key=()=>crypto.randomUUID().replaceAll('-','').slice(0,8), pretty=s=>String(s).replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const icons={plus:'M12 5v14M5 12h14',upload:'M12 16V4m-4 4 4-4 4 4M4 15v5h16v-5',download:'M12 4v12m-4-4 4 4 4-4M4 17v3h16v-3',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6m-6 4h6',close:'M6 6l12 12M18 6 6 18',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',target:'M12 2v4m0 12v4M2 12h4m12 0h4M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',archive:'M3 4h18v5H3zM5 9v11h14V9M9 13h6',restore:'M3 11a9 9 0 1 1 2 7M3 4v7h7',folder:'M3 6h7l2 3h9v11H3z',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6zM8 10V7a4 4 0 0 1 8 0v3',copy:'M8 8h13v13H8zM16 8V3H3v13h5',play:'m8 4 12 8-12 8z',pause:'M8 4v16m8-16v16',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7m2-5v6l4 2',arrow:'M4 12h16m-6-6 6 6-6 6'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const state={data:null,view:'documents',selected:null,checked:new Set(),page:1,mode:'review',mobile:'source',filter:'active',search:'',template:null,templateId:null,templateDirty:false,reviewDirty:false,pick:null,highlight:null,busy:false,jobTimer:null,folderTarget:null};
const statusText={imported:'Ready to process',uploaded:'Ready to process',queued:'Queued',processing:'Processing',running:'Processing',validated:'Checks passed',needs_review:'Needs review',approved:'Approved',approved_with_exceptions:'Approved with exceptions',failed:'Processing failed',cancelled:'Cancelled',ignored:'Duplicate ignored'};
const isApproved=d=>['approved','approved_with_exceptions'].includes(d?.status);
const dateLabel=value=>new Date(typeof value==='number'?value*1000:value).toLocaleString();
const doc=()=>state.data?.documents.find(d=>d.id===state.selected);
const activeTemplates=()=>state.data?.templates.filter(t=>!t.archived)||[];
const templateFor=d=>d?.templateSnapshot||state.data?.templates.find(t=>t.id===d?.templateId)||state.template||state.data?.defaultTemplate;
const fieldDefs=d=>{const t=templateFor(d),values=d?.result?.fields||{},known=t?.fields||[];return [...known.filter(f=>Object.hasOwn(values,f.name)),...Object.keys(values).filter(name=>!known.some(f=>f.name===name)).map(name=>({name,label:pretty(name),type:'text',required:false}))]};
const itemDefs=d=>{const t=templateFor(d),known=t?.table?.enabled?t.table.columns||[]:[],keys=[...new Set((d?.result?.items||[]).flatMap(r=>Object.keys(r).filter(k=>k!=='evidence')))];return [...known,...keys.filter(name=>!known.some(c=>c.name===name)).map(name=>({name,label:pretty(name),type:'text'}))]};
const selection=()=>state.checked.size?[...state.checked]:state.selected?[state.selected]:[];
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#notifications').append(el);setTimeout(()=>el.remove(),error?9000:4500)}
async function request(path,body,method='POST',binary=false){const options={method:body===undefined?'GET':method,credentials:'same-origin',headers:{}};if(body!==undefined){options.headers['X-CSRF-Token']=state.data?.csrfToken||'';if(body instanceof FormData)options.body=body;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}}const r=await fetch(path,options);if(!r.ok){let payload={};try{payload=await r.json()}catch{}const e=new Error(payload.error||'This action could not be completed.');e.status=r.status;e.issues=payload.issues;e.blockedDocuments=payload.blockedDocuments;throw e}return binary?r:r.status===204?{}:r.json()}
async function action(fn){if(state.busy)return;state.busy=true;document.body.setAttribute('aria-busy','true');try{await fn()}catch(e){toast(e.message,true);if(e.status===401)renderLogin();if(e.status===409&&!e.issues)toast('Refresh this document to see its latest saved state before trying again.',true)}finally{state.busy=false;document.body.removeAttribute('aria-busy')}}
async function refresh(renderAll=true){if(!renderAll&&(state.reviewDirty||state.templateDirty)){schedulePoll();return}try{state.data=await request('/api/state');$('#connection-error').classList.add('hidden');if(!state.template){const t=activeTemplates().find(t=>t.id===state.data.settings?.defaultTemplateId)||activeTemplates()[0];state.template=clone(t||state.data.defaultTemplate);state.templateId=t?.id||null}if(state.selected&&!doc())state.selected=null;for(const id of state.checked)if(!state.data.documents.some(d=>d.id===id))state.checked.delete(id);if(renderAll)render();else if(state.view==='documents'){renderLibrary();const d=doc();if(d&&!state.reviewDirty&&!state.templateDirty){renderSource();renderInspector()}}schedulePoll()}catch(e){if(e.status===401){clearTimeout(state.jobTimer);renderLogin()}else{const panel=$('#connection-error');panel.innerHTML=`<span>Fieldwork could not refresh. Your saved documents remain on this Mac.</span><button id="retry-connection" class="small">Retry</button>`;panel.classList.remove('hidden');$('#retry-connection').onclick=()=>refresh(true);schedulePoll(6000)}}}
function schedulePoll(delay){clearTimeout(state.jobTimer);const active=state.data?.jobs?.some(j=>['running','queued'].includes(j.status));state.jobTimer=setTimeout(()=>refresh(false),delay||(active?2000:12000))}
function renderLogin(){state.data=null;$('#main').innerHTML=`<div class="welcome"><img src="/static/fieldwork.svg" width="44" height="44" alt=""><h1>Open your local workspace.</h1><p>Launch Fieldwork from Applications to sign in automatically. For browser access, enter the local access key shown by the launcher.</p><form id="login-form"><label>Local access key<input id="access-key" type="password" autocomplete="off" required spellcheck="false"></label><button class="primary wide" type="submit">Open workspace</button><p id="login-error" class="inline-error" role="alert"></p></form><p class="privacy-note">${icon('lock')}This key unlocks documents stored on this Mac. It is not an online account password.</p></div>`;$('#login-form').onsubmit=e=>{e.preventDefault();action(async()=>{try{await request('/api/session',{token:$('#access-key').value});$('#access-key').value='';await refresh()}catch(err){$('#login-error').textContent=err.message}})}}
function render(){if(!state.data)return;$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(state.view==='documents')renderWorkspace();if(state.view==='templates')renderTemplates();if(state.view==='watch')renderWatches();if(state.view==='settings')renderSettings()}
async function allowDiscard(){if(!state.reviewDirty&&!state.templateDirty)return true;if(!await confirmAction('Leave unsaved changes?','Your saved document and template will remain unchanged.','Discard changes'))return false;try{if(state.reviewDirty&&doc()){const saved=await request(`/api/documents/${encodeURIComponent(state.selected)}`);state.data.documents=state.data.documents.map(d=>d.id===saved.id?saved:d)}if(state.templateDirty)state.template=clone(state.data.templates.find(t=>t.id===state.templateId)||state.data.defaultTemplate);state.reviewDirty=state.templateDirty=false;return true}catch(e){toast(e.message,true);return false}}
async function navigate(view){if(!await allowDiscard())return;state.view=view;state.reviewDirty=state.templateDirty=false;state.pick=null;render()}
function renderWorkspace(){$('#main').innerHTML=`<div class="workspace"><aside class="library" aria-label="Document library"><div class="library-top"><div class="library-heading"><h1>Documents</h1><span id="document-count" class="count"></span></div><button id="import-files" class="primary import-button">${icon('plus')}Import documents</button><label class="search-field"><span class="visually-hidden">Search documents</span>${icon('search')}<input id="document-search" type="search" value="${esc(state.search)}" placeholder="Search documents…"></label><div class="filter-row"><select id="document-filter" aria-label="Filter documents">${[['active','All documents'],['needs_review','Needs review'],['approved','Approved'],['unprocessed','Not processed'],['archived','Archived']].map(([v,l])=>`<option value="${v}" ${v===state.filter?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="library-select"><label class="check"><input id="select-visible" type="checkbox">Select visible</label><button id="archive-selected" class="quiet small">${state.filter==='archived'?'Restore':'Archive'}</button></div><div id="document-list" class="document-list" role="list"></div><div id="jobs" class="jobs-box hidden" aria-live="polite"></div><div class="library-bottom"><select id="batch-template" aria-label="Template to apply">${templateOptions(state.templateId)}</select><span id="selection-info" class="selection-info"></span><div class="button-row"><button id="process-selected" class="primary">${icon('play')}Process</button><button id="open-export">${icon('download')}Export</button></div></div></aside><div class="mobile-workspace-tabs"><button id="mobile-source">Source</button><button id="mobile-review">Review & template</button></div><section id="source-pane" class="source-pane" aria-label="Original document"></section><aside id="inspector" class="inspector" aria-label="Document review"><nav class="inspector-tabs" aria-label="Document tools"><button data-mode="review">Review data</button><button data-mode="teach">Teach template</button></nav><div id="inspector-body" class="inspector-body"></div></aside></div>`;$('#import-files').onclick=()=>$('#file-picker').click();$('#document-search').oninput=e=>{state.search=e.target.value;renderLibrary()};$('#document-filter').onchange=e=>{state.filter=e.target.value;state.checked.clear();renderLibrary()};$('#select-visible').onchange=e=>{for(const d of visibleDocuments())e.target.checked?state.checked.add(d.id):state.checked.delete(d.id);renderLibrary()};$('#archive-selected').onclick=()=>archiveSelected();$('#process-selected').onclick=()=>processSelected();$('#open-export').onclick=()=>showExport();$('#batch-template').onchange=e=>{state.templateId=e.target.value||null;const t=state.data.templates.find(t=>t.id===state.templateId);if(t&&!state.templateDirty)state.template=clone(t);renderInspector()};$$('[data-mode]').forEach(b=>b.onclick=async()=>{if(state.mode!==b.dataset.mode&&!await allowDiscard())return;state.mode=b.dataset.mode;state.reviewDirty=false;state.pick=null;renderInspector();renderSource()});$('#mobile-source').onclick=()=>{state.mobile='source';renderMobile()};$('#mobile-review').onclick=()=>{state.mobile='review';renderMobile()};renderLibrary();renderSource();renderInspector();renderMobile()}
function templateOptions(id,blank='Choose template…'){return `<option value="">${blank}</option>`+activeTemplates().map(t=>`<option value="${esc(t.id)}" ${t.id===id?'selected':''}>${esc(t.name)}</option>`).join('')}
function visibleDocuments(){return state.data.documents.filter(d=>{const status=d.status;return (state.filter==='archived'?d.archived:!d.archived)&&(state.filter==='needs_review'?status==='needs_review'||status==='failed':state.filter==='approved'?isApproved(d):state.filter==='unprocessed'?['uploaded','imported','cancelled','failed'].includes(status):true)&&(!state.search||d.name.toLowerCase().includes(state.search.toLowerCase()))})}
function renderLibrary(){if(!$('#document-list'))return;const docs=visibleDocuments();$('#document-count').textContent=state.data.documents.filter(d=>!d.archived).length;$('#document-list').innerHTML=docs.length?docs.map(d=>`<div class="document-row ${d.id===state.selected?'selected':''}" role="listitem"><input type="checkbox" data-check="${esc(d.id)}" ${state.checked.has(d.id)?'checked':''} aria-label="Select ${esc(d.name)}"><button class="document-open" data-document="${esc(d.id)}"><span class="document-name">${esc(d.name)}</span><span class="document-meta"><span class="status ${esc(d.status)}">${esc(d.archived?'Archived':statusText[d.status]||pretty(d.status))}</span>${d.result?.ocr?'<span>· OCR</span>':''}</span></button></div>`).join(''):`<div class="empty-library">${state.search?'No matching documents. Try a different search.':state.filter==='archived'?'Archived documents will appear here.':state.filter!=='active'?'No documents in this view.':'Import a PDF or image to begin.'}</div>`;$$('[data-check]').forEach(el=>el.onchange=()=>{el.checked?state.checked.add(el.dataset.check):state.checked.delete(el.dataset.check);renderLibrary()});$$('[data-document]').forEach(b=>b.onclick=()=>selectDocument(b.dataset.document));$('#select-visible').checked=docs.length>0&&docs.every(d=>state.checked.has(d.id));$('#select-visible').indeterminate=docs.some(d=>state.checked.has(d.id))&&!$('#select-visible').checked;$('#selection-info').textContent=state.checked.size?`${state.checked.size} selected`:state.selected?'Current document':'Select documents to process';$('#process-selected').disabled=!selection().length||!state.templateId;$('#archive-selected').disabled=!selection().length;renderJobs()}
async function selectDocument(id){if(id===state.selected)return;if(!await allowDiscard())return;state.selected=id;state.page=1;state.highlight=null;state.pick=null;state.reviewDirty=false;state.mode=doc()?.result?'review':'teach';renderLibrary();renderSource();renderInspector()}
function renderJobs(){const jobs=state.data.jobs.filter(j=>['queued','running','failed','cancelled'].includes(j.status)).slice(-8);const el=$('#jobs');if(!el)return;el.classList.toggle('hidden',!jobs.length);el.innerHTML=jobs.map(j=>{const d=state.data.documents.find(d=>d.id===j.documentId);return `<div class="job"><div class="job-heading"><span>${esc(d?.name||'Document')}</span><span>${esc(pretty(j.status))}</span></div><progress class="job-progress" max="100" value="${Number(j.progress)||0}" aria-label="${esc(d?.name||'Document')} progress"></progress>${j.error?`<p class="inline-error">${esc(j.error)}</p>`:''}<div class="job-actions">${['queued','running'].includes(j.status)?`<button class="small quiet" data-job-cancel="${esc(j.id)}">Cancel</button>`:`<button class="small" data-job-retry="${esc(j.id)}">Retry</button>`}</div></div>`}).join('');$$('[data-job-cancel]').forEach(b=>b.onclick=()=>action(async()=>{await request(`/api/jobs/${encodeURIComponent(b.dataset.jobCancel)}/cancel`,{});await refresh(false)}));$$('[data-job-retry]').forEach(b=>b.onclick=()=>action(async()=>{await request(`/api/jobs/${encodeURIComponent(b.dataset.jobRetry)}/retry`,{});await refresh(false)}))}
function renderMobile(){$('#source-pane')?.classList.toggle('mobile-hidden',state.mobile!=='source');$('#inspector')?.classList.toggle('mobile-hidden',state.mobile!=='review');$('#mobile-source')?.classList.toggle('active',state.mobile==='source');$('#mobile-review')?.classList.toggle('active',state.mobile==='review')}
function renderSource(){const d=doc(),el=$('#source-pane');if(!el)return;if(!d){el.innerHTML=`<div class="welcome"><div class="welcome-mark">${icon('file')}</div><h1>Documents in.<br>Useful data out.</h1><p>Show Fieldwork the fields you need, review the results beside the original, then export your approved data.</p><div class="welcome-actions"><button id="welcome-import" class="primary">${icon('upload')}Import documents</button>${state.data.samples?.length?'<button id="welcome-samples">Try example documents</button>':''}</div><p class="privacy-note">${icon('lock')}Documents stay on this Mac. Text and image processing work locally, without API keys.</p></div>`;$('#welcome-import').onclick=()=>$('#file-picker').click();$('#welcome-samples')?.addEventListener('click',()=>loadExamples());return}state.page=Math.min(Math.max(state.page,1),Math.max(d.pages?.length||1,1));const p=d.pages?.[state.page-1];el.innerHTML=`<div class="source-toolbar"><div class="source-title"><h2 title="${esc(d.name)}">${esc(d.name)}</h2><span class="status ${esc(d.status)}">${esc(statusText[d.status]||pretty(d.status))}</span></div><div class="source-controls"><button id="previous-page" aria-label="Previous page" ${state.page<=1?'disabled':''}>${icon('left')}</button><span>${state.page} / ${d.pages?.length||1}</span><button id="next-page" aria-label="Next page" ${state.page>=(d.pages?.length||1)?'disabled':''}>${icon('right')}</button><a class="button small download-source" download href="/api/documents/${encodeURIComponent(d.id)}/source" title="Download original" aria-label="Download original">${icon('download')}</a><button id="document-history" aria-label="Document activity">${icon('history')}</button></div></div><div id="source-scroll" class="source-scroll"><div id="paper" class="paper"><img id="page-image" src="/api/documents/${encodeURIComponent(d.id)}/page/${state.page}" alt="Page ${state.page} of ${esc(d.name)}"><div id="overlays" class="overlays"></div></div></div><div class="source-footer">${icon('eye')}<span id="source-hint">${p?.ocr?'This page was read with local OCR. Check characters and amounts against the original.':state.mode==='teach'?'Choose a label from the page, or adjust table column dividers.':'Use “See source” to check a value against the original.'}</span></div>`;$('#previous-page').onclick=()=>{state.page--;state.highlight=null;renderSource()};$('#next-page').onclick=()=>{state.page++;state.highlight=null;renderSource()};$('#document-history').onclick=()=>showAudit(d.id);$('#page-image').onerror=()=>{$('#source-hint').textContent='The source preview could not load. Download the original to inspect it.'};renderOverlays()}
function positionBox(el,bbox,page){if(!bbox||!page)return;Object.assign(el.style,{left:`${bbox[0]/page.width*100}%`,top:`${bbox[1]/page.height*100}%`,width:`${(bbox[2]-bbox[0])/page.width*100}%`,height:`${(bbox[3]-bbox[1])/page.height*100}%`})}
function renderOverlays(){const overlay=$('#overlays'),d=doc(),p=d?.pages?.[state.page-1];if(!overlay||!p)return;overlay.replaceChildren();if(state.pick){$('#source-hint').textContent=`Select the printed label for ${state.pick.label}.`;for(const line of p.lines||[]){const b=document.createElement('button');b.className='anchor-pick';b.setAttribute('aria-label',`Use label: ${line.text}`);b.title=line.text;positionBox(b,line.bbox,p);b.onclick=()=>{const lineText=line.text;const anchor=lineText.includes(':')?lineText.slice(0,lineText.indexOf(':')+1):lineText;state.template.fields.find(f=>f.name===state.pick.name).anchor=anchor;state.templateDirty=true;state.pick=null;state.mobile='review';renderInspector();renderOverlays();renderMobile();toast(`Label selected: ${anchor}`)};overlay.append(b)}}else if(state.mode==='teach'&&state.template?.table?.enabled){const cols=state.template.table.columns;cols.slice(1).forEach((col,i)=>{const guide=document.createElement('button');guide.className='column-guide';guide.style.left=`${col.x0*100}%`;guide.setAttribute('aria-label',`Boundary before ${col.label||pretty(col.name)}; use arrow keys to adjust`);guide.innerHTML=`<span>${i+1}</span>`;const move=value=>{const v=Math.max(cols[i].x0+.015,Math.min(cols[i+1].x1-.015,value));cols[i].x1=cols[i+1].x0=v;state.templateDirty=true;guide.style.left=`${v*100}%`};guide.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();move(col.x0+(e.key==='ArrowLeft'?-.005:.005));renderInspector()}};guide.onpointerdown=e=>{guide.setPointerCapture(e.pointerId);guide.onpointermove=event=>{const bounds=$('#paper').getBoundingClientRect();move((event.clientX-bounds.left)/bounds.width)};guide.onpointerup=()=>{guide.onpointermove=null;renderInspector()}};overlay.append(guide)})}if(state.highlight?.page===state.page){const h=document.createElement('div');h.className='evidence-highlight';positionBox(h,state.highlight.bbox,p);overlay.append(h)}}
function showEvidence(evidence){if(!evidence?.bbox){toast('No source location is available for this value.');return}state.highlight=evidence;state.page=evidence.page;state.mobile='source';renderSource();renderMobile();requestAnimationFrame(()=>{const p=doc().pages[state.page-1];$('#source-scroll')?.scrollTo({top:Math.max(0,evidence.bbox[1]/p.height*$('#paper').offsetHeight-100),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})})}
function renderInspector(){$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===state.mode));if(!$('#inspector-body'))return;if(state.mode==='teach')renderTemplateEditor($('#inspector-body'),true);else renderReview()}
function inputFor(def,value,attrs=''){return def.type==='text'&&String(value??'').length>65?`<textarea ${attrs}>${esc(value)}</textarea>`:`<input ${attrs} value="${esc(value)}" ${['number','currency'].includes(def.type)?'inputmode="decimal" class="numeric"':def.type==='email'?'inputmode="email"':''}>`}
function markReviewDirty(){state.reviewDirty=true;const badge=$('#inspector-body .badges .badge');if(badge){badge.textContent='Unsaved changes';badge.classList.add('warning')}}
function renderReview(){const d=doc(),r=d?.result,el=$('#inspector-body');if(!r){el.innerHTML=`<div class="empty-panel"><h2>${d?'Ready when you are.':'Start with a document.'}</h2><p>${d?'Choose a template or teach a new one, then process this document.':'Import a PDF or image. Your extracted fields will appear here, alongside the original.'}</p><button id="switch-teach">${d?'Teach a template':'Create a template'}${icon('arrow')}</button></div>`;$('#switch-teach').onclick=()=>{state.mode='teach';renderInspector();renderOverlays()};return}const fields=fieldDefs(d),cols=itemDefs(d),issues=r.issues||[];el.innerHTML=`<div class="badges"><span class="badge ${issues.length?'warning':''}">${esc(state.reviewDirty?'Unsaved changes':d.status==='approved_with_exceptions'?'Approved with exceptions':d.status==='approved'?'Approved for export':issues.length?`${issues.length} item${issues.length===1?'':'s'} to check`:'Automatic checks passed')}</span>${r.ocr?'<span class="badge neutral">Local OCR</span>':''}${d.templateVersion?`<span class="badge neutral">Template v${d.templateVersion}</span>`:''}</div>${d.approvalNote?`<div class="issue-panel"><h3>Approval note</h3><p>${esc(d.approvalNote)}</p></div>`:''}${d.archived?'<div class="issue-panel"><h3>Archived document</h3><p>Restore this document to process or export it.</p><button id="restore-current">Restore document</button></div>':''}${issues.length?`<div class="issue-panel"><h3>Check before approving</h3><ul>${issues.map(i=>`<li>${esc(i.message)}</li>`).join('')}</ul>${issues.some(i=>String(i.code).includes('duplicate'))||d.duplicateOf?'<button id="resolve-duplicate">Resolve duplicate</button>':''}</div>`:'<p class="intro">Check the data against the original before approving. Automatic checks do not establish that every value is correct.</p>'}<div class="form-grid">${fields.map((f,i)=>`<label class="review-field ${i===0?'full':''}">${esc(f.label||pretty(f.name))}${inputFor(f,r.fields[f.name],`data-field="${esc(f.name)}"`)}<button class="source-link" data-evidence="${esc(f.name)}" type="button">${icon('eye')}See source</button></label>`).join('')}</div>${cols.length?`<div class="section-heading"><h3>Line items</h3><button id="add-row" class="small">${icon('plus')}Add row</button></div><div id="review-rows">${renderRows(r.items,cols)}</div>`:''}<div class="review-actions"><div class="button-row"><button id="save-review">Save & check</button><button id="approve-document" class="primary" ${d.archived?'disabled':''}>Approve</button></div>${isApproved(d)?'<button id="revoke-approval" class="quiet">Revoke approval</button>':''}<p class="hint">Changes revoke approval. Only approved, unarchived documents are included in exports.</p></div>`;$$('[data-field],[data-item]').forEach(e=>e.oninput=()=>{markReviewDirty()});$$('[data-evidence]').forEach(b=>b.onclick=()=>showEvidence(r.evidence?.[b.dataset.evidence]));bindRows();$('#add-row')?.addEventListener('click',()=>{const draft=readReview();draft.items.push(Object.fromEntries(cols.map(c=>[c.name,''])));r.fields=draft.fields;r.items=draft.items;state.reviewDirty=true;renderReview();$$('[data-item]').at(-cols.length)?.focus()});$('#restore-current')?.addEventListener('click',()=>archiveIds([d.id],false));$('#resolve-duplicate')?.addEventListener('click',()=>showDuplicate());$('#save-review').onclick=()=>action(async()=>{await saveReview();await refresh();toast('Changes saved and checked.')});$('#approve-document').onclick=()=>action(async()=>{await saveReview();await refresh();await approveCurrent()});$('#revoke-approval')?.addEventListener('click',()=>action(async()=>{await request(`/api/documents/${encodeURIComponent(d.id)}/revoke`,{revision:d.reviewRevision});await refresh();toast('Approval revoked. This document is excluded from export.')}))}
function renderRows(rows,cols){return rows.length?rows.map((item,i)=>`<div class="row-card"><div class="row-card-head"><span>Row ${i+1}</span><div class="button-row tight"><button class="source-link" data-row-evidence="${i}">${icon('eye')}See source</button><button class="icon-button small quiet" data-delete-row="${i}" aria-label="Delete row ${i+1}">${icon('trash')}</button></div></div><div class="form-grid">${cols.map((c,j)=>`<label class="${j===0?'full':''}">${esc(c.label||pretty(c.name))}${inputFor(c,item[c.name],`data-item="${i}" data-column="${esc(c.name)}"`)}</label>`).join('')}</div></div>`).join(''):'<p class="hint">No rows yet. Add a row to enter data from the original.</p>'}
function bindRows(){$$('[data-row-evidence]').forEach(b=>b.onclick=()=>showEvidence(doc().result.items[+b.dataset.rowEvidence]?.evidence));$$('[data-delete-row]').forEach(b=>b.onclick=()=>{const draft=readReview();draft.items.splice(+b.dataset.deleteRow,1);doc().result.fields=draft.fields;doc().result.items=draft.items;state.reviewDirty=true;renderReview()});$$('[data-item]').forEach(e=>e.oninput=markReviewDirty)}
function readReview(){const d=doc(),fields={...d.result.fields},items=d.result.items.map(item=>({...Object.fromEntries(itemDefs(d).map(c=>[c.name,String(item[c.name]??'')])),...(item.evidence?{evidence:clone(item.evidence)}:{})}));$$('[data-field]').forEach(el=>fields[el.dataset.field]=el.value);$$('[data-item]').forEach(el=>{if(items[+el.dataset.item])items[+el.dataset.item][el.dataset.column]=el.value});return{fields,items,revision:d.reviewRevision}}
async function saveReview(){const d=doc();const data=readReview();data.items=data.items.map(({evidence,...values})=>values);const result=await request(`/api/documents/${encodeURIComponent(d.id)}/review`,data);state.reviewDirty=false;return result}
async function approveCurrent(){const d=doc(),issues=d.result?.issues||[];if(issues.some(i=>String(i.code).includes('duplicate'))&&!d.duplicateDecision)return showDuplicate();if(issues.length){showDialog('Approve with unresolved issues?',`<p>Check each issue against the source. Your reason will be saved with this document and included in the export.</p><div class="issue-panel"><ul>${issues.map(i=>`<li>${esc(i.message)}</li>`).join('')}</ul></div><label>Reason for approving<textarea id="approval-note" minlength="10" placeholder="What did you verify, and why should this be kept?"></textarea></label><div class="dialog-actions"><button data-close>Back to review</button><button id="confirm-approval" class="primary">Approve with reason</button></div>`);$('#confirm-approval').onclick=()=>action(async()=>{const note=$('#approval-note').value.trim();if(note.length<10){toast('Add a reason of at least 10 characters.',true);return}if(await submitApproval({revision:d.reviewRevision,override:true,note})){closeDialog();await refresh();toast('Document approved with exceptions and your review note.')}});return}if(await submitApproval({revision:d.reviewRevision})){await refresh();toast('Document approved for export.')}}
async function submitApproval(payload){try{await request(`/api/documents/${encodeURIComponent(doc().id)}/approve`,payload);return true}catch(e){if(e.status===409){closeDialog();await refresh();if(e.issues&&doc()?.result)doc().result.issues=e.issues;toast(e.message,true);if(doc()?.result?.issues?.length)await approveCurrent();return false}throw e}}
function showDuplicate(){const d=doc(),others=state.data.documents.filter(o=>o.id!==d.id&&(o.id===d.duplicateOf||o.duplicateOf===d.id));showDialog('Resolve this duplicate',`<p>This document shares the template’s duplicate identifiers with another import. Ignore this copy to keep it out of exports, or explicitly keep both when they represent different records.</p><div class="issue-panel"><h3>${esc(d.name)}</h3>${others.map(o=>`<p>Other copy: <button class="quiet" data-open-duplicate="${esc(o.id)}">${esc(o.name)}</button></p>`).join('')}<ul>${(d.result?.issues||[]).filter(i=>String(i.code).includes('duplicate')).map(i=>`<li>${esc(i.message)}</li>`).join('')}</ul></div><label>Decision note<textarea id="duplicate-note" placeholder="Explain why this is a duplicate to ignore, or why both records should be kept."></textarea></label><div class="dialog-actions"><button data-close>Cancel</button><button id="ignore-copy">Ignore this duplicate</button><button id="keep-copy" class="primary">Keep both</button></div>`);$$('[data-open-duplicate]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.openDuplicate;state.page=1;state.reviewDirty=false;closeDialog();render()});for(const decision of ['keep','ignore'])$('#'+decision+'-copy').onclick=()=>action(async()=>{const note=$('#duplicate-note').value.trim();if(!note){toast('Add a short note explaining your choice.',true);return}await request(`/api/documents/${encodeURIComponent(d.id)}/duplicate`,{decision,note});closeDialog();await refresh();toast(decision==='ignore'?'Copy ignored and excluded from export.':'Both copies retained by your decision. Review remaining issues before approving.')})}
async function processSelected(){if(!await allowDiscard())return;const ids=selection().filter(id=>!state.data.documents.find(d=>d.id===id)?.archived);if(!ids.length||!state.templateId)return;await action(async()=>{await request('/api/jobs',{templateId:state.templateId,documentIds:ids});state.reviewDirty=false;await refresh(false);toast(`${ids.length} document${ids.length===1?'':'s'} queued.`)})}
async function archiveSelected(){const ids=selection();if(!ids.length)return;await archiveIds(ids,state.filter!=='archived')}
async function archiveIds(ids,archived){await action(async()=>{if(archived&&!await confirmAction('Archive selected documents?',`${ids.length} document${ids.length===1?'':'s'} will be excluded from processing and export. You can restore them from Archived. Queued work will be cancelled.`,'Archive'))return;for(const id of ids)await request(`/api/documents/${encodeURIComponent(id)}/archive`,{archived});state.checked.clear();await refresh();toast(archived?'Documents archived.':'Documents restored.')})}
async function importFiles(files){if(!await allowDiscard())return;const accepted=[...files].filter(f=>/\.(pdf|png|jpe?g|tiff?)$/i.test(f.name));if(!accepted.length){toast('Choose PDF, PNG, JPEG or TIFF files.',true);return}await action(async()=>{const form=new FormData();accepted.forEach(f=>form.append('files',f));const result=await request('/api/upload',form);state.selected=result.ids?.[0]||state.selected;state.checked=new Set(result.ids||[]);state.view='documents';state.filter='active';state.mode='teach';state.page=1;state.reviewDirty=false;await refresh();toast(`${result.ids?.length||accepted.length} document${accepted.length===1?'':'s'} imported. Choose a template to process them.`)})}
async function loadExamples(){await action(async()=>{const samples=state.data.samples||[];let first;for(const sample of samples){const name=typeof sample==='string'?sample:sample.name;const r=await request('/api/samples',{name});first??=r.id}state.selected=first;state.mode='teach';state.page=1;await refresh();toast('Fictional examples imported. Your own documents remain unchanged.')})}
function renderTemplates(){const list=state.data.templates.filter(t=>state.showArchivedTemplates?true:!t.archived);$('#main').innerHTML=`<div class="page"><div class="page-heading"><div><h1>Templates</h1><p>Teach a recurring document once. Reuse its fields and table rules for the next batch.</p></div><div class="button-row tight"><button id="import-template">${icon('upload')}Import</button><button id="new-template" class="primary">${icon('plus')}New template</button></div></div><div class="template-layout"><div><label class="check"><input id="show-archived-templates" type="checkbox" ${state.showArchivedTemplates?'checked':''}>Include archived</label><div class="template-list">${list.length?list.map(t=>`<button class="template-item ${t.id===state.templateId?'active':''}" data-template="${esc(t.id)}"><strong>${esc(t.name)}</strong><small>${t.fields.length} fields${t.table?.enabled?` · ${t.table.columns.length} table columns`:''} · v${t.version||1}${t.archived?' · Archived':''}</small></button>`).join(''):'<p class="hint">No saved templates yet. Create one here or teach it beside an imported document.</p>'}</div></div><section id="template-editor" class="template-editor" aria-label="Template editor"></section></div></div>`;$('#new-template').onclick=()=>newTemplate();$('#import-template').onclick=()=>$('#template-picker').click();$('#show-archived-templates').onchange=e=>{state.showArchivedTemplates=e.target.checked;renderTemplates()};$$('[data-template]').forEach(b=>b.onclick=async()=>{if(!await allowDiscard())return;state.templateId=b.dataset.template;state.template=clone(state.data.templates.find(t=>t.id===state.templateId));state.templateDirty=false;renderTemplates()});renderTemplateEditor($('#template-editor'),false)}
const typeOptions=(value)=>['text','number','currency','date','email'].map(t=>`<option value="${t}" ${t===value?'selected':''}>${pretty(t)}</option>`).join('');
function renderTemplateEditor(el,inDocument){if(!state.template){el.innerHTML='<button id="first-template" class="primary">Create a template</button>';$('#first-template').onclick=()=>newTemplate();return}const t=state.template;const fields=t.fields||[];const table=t.table||{enabled:false,columns:[]};t.table=table;t.validation||={enabled:false};t.duplicate_fields||=[];t.export_columns||=[];el.innerHTML=`${inDocument?`<label>Template<select id="template-select">${templateOptions(state.templateId,'New template')}</select></label><div class="button-row tight"><button id="new-template-inline" class="small quiet">${icon('plus')}New template</button></div>`:''}<div class="section-heading"><h2>${state.templateId?'Edit template':'New template'}</h2>${t.version?`<span class="badge neutral">Version ${t.version}</span>`:''}</div><label>Template name<input id="template-name" value="${esc(t.name)}" maxlength="100" placeholder="For example: supplier invoices"></label><p class="hint">Labels find the values on each page. Saved updates create a new version; previous extractions retain their original template.</p><div class="section-heading"><h3>Fields</h3><button id="add-field" class="small">${icon('plus')}Add field</button></div><div id="field-definitions">${fields.map((f,i)=>`<div class="field-settings"><div class="field-settings-head"><input data-field-label="${i}" value="${esc(f.label||pretty(f.name))}" aria-label="Field ${i+1} name" placeholder="Field name"><button class="icon-button small quiet" data-delete-field="${i}" aria-label="Remove ${esc(f.label||f.name)}">${icon('trash')}</button></div><div class="form-grid"><label>Type<select data-field-type="${i}">${typeOptions(f.type||'text')}</select></label><label>Value appears<select data-field-position="${i}"><option value="after" ${f.position!=='below'?'selected':''}>After label</option><option value="below" ${f.position==='below'?'selected':''}>Below label</option></select></label><label class="full">Printed label<span class="anchor-input"><input data-anchor="${i}" value="${esc(f.anchor)}" placeholder="For example: Invoice number:">${inDocument?`<button data-pick-field="${i}" class="icon-button ${state.pick?.name===f.name?'primary':''}" aria-label="Choose ${esc(f.label||f.name)} label from source">${icon('target')}</button>`:''}</span></label></div><div class="checkbox-line"><label class="check"><input type="checkbox" data-field-required="${i}" ${f.required?'checked':''}>Required</label><label class="check"><input type="checkbox" data-duplicate-field="${esc(f.name)}" ${t.duplicate_fields.includes(f.name)?'checked':''}>Check duplicates</label></div></div>`).join('')}</div><div class="section-heading"><h3>Repeating table</h3><label class="check"><input id="table-enabled" type="checkbox" ${table.enabled?'checked':''}>Include</label></div>${table.enabled?`<div class="table-settings"><label>Table header starts with<input id="table-header" value="${esc(table.header_anchor||'')}" placeholder="Description"></label><div class="form-grid"><label>Stop before these lines<textarea id="table-ends" placeholder="Subtotal:\nContinued on next page">${esc((table.end_anchors||[]).join('\n'))}</textarea></label><label>Ignore lines starting with<textarea id="table-ignore" placeholder="Page \nContinued">${esc((table.ignore_prefixes||[]).join('\n'))}</textarea></label></div><p class="hint">Enter one label per line. Repeated headers find the table on each page.</p><div class="column-editor"><table><thead><tr><th>Column / type</th><th>From %</th><th>To %</th><th><span class="visually-hidden">Remove</span></th></tr></thead><tbody>${table.columns.map((c,i)=>`<tr><td><input data-col-label="${i}" value="${esc(c.label||pretty(c.name))}" aria-label="Column ${i+1} label"><select data-col-type="${i}" aria-label="Column ${i+1} type">${typeOptions(c.type||'text')}</select><label class="check"><input data-col-required="${i}" type="checkbox" ${c.required?'checked':''}>Required</label></td><td><input class="percent" data-col-bound="${i}" data-side="x0" type="number" min="0" max="100" step="0.1" value="${(c.x0*100).toFixed(1)}" aria-label="${esc(c.label||c.name)} start percent"></td><td><input class="percent" data-col-bound="${i}" data-side="x1" type="number" min="0" max="100" step="0.1" value="${(c.x1*100).toFixed(1)}" aria-label="${esc(c.label||c.name)} end percent"></td><td><button data-delete-column="${i}" class="icon-button small quiet" aria-label="Remove column ${i+1}">${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div><button id="add-column" class="small">${icon('plus')}Add column</button><p class="hint">Column limits are percentages of page width. ${inDocument?'Drag the dividers on the source, or enter exact limits here.':'Open a document to position dividers directly on its source.'}</p></div>`:''}<div class="section-heading"><h3>Financial checks</h3><label class="check"><input id="validation-enabled" type="checkbox" ${t.validation.enabled?'checked':''}>Enable</label></div>${t.validation.enabled?`<p class="hint">Check quantity × price, the sum of line totals, and subtotal + tax. Map each role to a field.</p><div class="form-grid">${['quantity','unit_price','line_total','subtotal','tax','total'].map(role=>{const defs=['quantity','unit_price','line_total'].includes(role)?table.columns:fields;return `<label>${pretty(role)}<select data-validation-role="${role}"><option value="">Choose field…</option>${defs.map(f=>`<option value="${esc(f.name)}" ${t.validation[role]===f.name?'selected':''}>${esc(f.label||pretty(f.name))}</option>`).join('')}</select></label>`}).join('')}</div>`:'<p class="hint">Leave this off for documents without financial totals.</p>'}<div class="review-actions"><button id="save-template" class="primary wide">Save template${state.templateDirty?' changes':''}</button>${inDocument?`<button id="test-template" ${!doc()?'disabled':''}>Save & process this document</button>`:''}${state.templateId?`<div class="button-row"><a class="button" download href="/api/templates/${encodeURIComponent(state.templateId)}/export">${icon('download')}Export template</a><button id="archive-template">${t.archived?'Restore':'Archive'}</button></div>`:''}</div>`;
const dirty=()=>state.templateDirty=true;const redraw=()=>{dirty();renderTemplateEditor(el,inDocument);if(inDocument)renderOverlays()};$('#template-select')?.addEventListener('change',async e=>{const id=e.target.value;if(!await allowDiscard()){e.target.value=state.templateId||'';return}state.templateId=id||null;state.template=clone(state.data.templates.find(t=>t.id===id)||state.data.defaultTemplate);state.templateDirty=false;renderTemplateEditor(el,inDocument);renderOverlays()});$('#new-template-inline')?.addEventListener('click',()=>newTemplate());$('#template-name').oninput=e=>{t.name=e.target.value;dirty()};$$('[data-field-label]').forEach(e=>e.oninput=()=>{fields[+e.dataset.fieldLabel].label=e.value;dirty()});$$('[data-field-type]').forEach(e=>e.onchange=()=>{fields[+e.dataset.fieldType].type=e.value;dirty()});$$('[data-field-position]').forEach(e=>e.onchange=()=>{fields[+e.dataset.fieldPosition].position=e.value;dirty()});$$('[data-anchor]').forEach(e=>e.oninput=()=>{fields[+e.dataset.anchor].anchor=e.value;dirty()});$$('[data-field-required]').forEach(e=>e.onchange=()=>{fields[+e.dataset.fieldRequired].required=e.checked;dirty()});$$('[data-duplicate-field]').forEach(e=>e.onchange=()=>{t.duplicate_fields=e.checked?[...new Set([...t.duplicate_fields,e.dataset.duplicateField])]:t.duplicate_fields.filter(n=>n!==e.dataset.duplicateField);dirty()});$$('[data-pick-field]').forEach(b=>b.onclick=()=>{if(!doc())return toast('Import or select a document first.');const f=fields[+b.dataset.pickField];state.pick=state.pick?.name===f.name?null:{name:f.name,label:f.label||pretty(f.name)};state.mobile='source';renderTemplateEditor(el,inDocument);renderOverlays();renderMobile()});$('#add-field').onclick=()=>{fields.push({name:'field_'+key(),label:'New field',type:'text',required:true,anchor:'',position:'after'});redraw();$$('[data-field-label]').at(-1)?.focus()};$$('[data-delete-field]').forEach(b=>b.onclick=()=>{const f=fields.splice(+b.dataset.deleteField,1)[0];t.duplicate_fields=t.duplicate_fields.filter(n=>n!==f.name);redraw()});$('#table-enabled').onchange=e=>{table.enabled=e.target.checked;if(table.enabled&&!table.columns.length)table.columns=[{name:'description',label:'Description',type:'text',required:true,x0:.05,x1:.6},{name:'amount',label:'Amount',type:'currency',required:true,x0:.6,x1:.95}];redraw()};$('#table-header')?.addEventListener('input',e=>{table.header_anchor=e.target.value;dirty()});$('#table-ends')?.addEventListener('input',e=>{table.end_anchors=e.target.value.split('\n').map(v=>v.trim()).filter(Boolean);dirty()});$('#table-ignore')?.addEventListener('input',e=>{table.ignore_prefixes=e.target.value.split('\n').map(v=>v.trim()).filter(Boolean);dirty()});$$('[data-col-label]').forEach(e=>e.oninput=()=>{table.columns[+e.dataset.colLabel].label=e.value;dirty()});$$('[data-col-type]').forEach(e=>e.onchange=()=>{table.columns[+e.dataset.colType].type=e.value;dirty()});$$('[data-col-required]').forEach(e=>e.onchange=()=>{table.columns[+e.dataset.colRequired].required=e.checked;dirty()});$$('[data-col-bound]').forEach(e=>e.onchange=()=>{table.columns[+e.dataset.colBound][e.dataset.side]=Number(e.value)/100;dirty();if(inDocument)renderOverlays()});$('#add-column')?.addEventListener('click',()=>{table.columns.push({name:'column_'+key(),label:'New column',type:'text',required:false,x0:0,x1:1});const width=.9/table.columns.length;table.columns.forEach((c,i)=>{c.x0=.05+i*width;c.x1=.05+(i+1)*width});redraw()});$$('[data-delete-column]').forEach(b=>b.onclick=()=>{table.columns.splice(+b.dataset.deleteColumn,1);redraw()});$('#validation-enabled').onchange=e=>{t.validation.enabled=e.target.checked;redraw()};$$('[data-validation-role]').forEach(e=>e.onchange=()=>{t.validation[e.dataset.validationRole]=e.value;dirty()});$('#save-template').onclick=()=>action(async()=>{await saveTemplate();await refresh();toast('Template saved. Existing documents retain their previous version.')});$('#test-template')?.addEventListener('click',()=>action(async()=>{await saveTemplate();await request('/api/jobs',{templateId:state.templateId,documentIds:[state.selected]});state.mode='review';state.pick=null;await refresh();toast('Document queued with the saved template.')}));$('#archive-template')?.addEventListener('click',()=>action(async()=>{await request(`/api/templates/${encodeURIComponent(state.templateId)}/archive`,{archived:!t.archived});const archived=!t.archived;state.template.archived=archived;await refresh();toast(archived?'Template archived. Previous extractions are retained.':'Template restored.')}))}
async function saveTemplate(){const t=clone(state.template);delete t.id;delete t.version;delete t.archived;const sources=[{source:'source_file',label:'Source file'},...t.fields.map(f=>({source:'fields.'+f.name,label:f.label||pretty(f.name)})),...(t.table?.enabled?t.table.columns.map(c=>({source:'items.'+c.name,label:c.label||pretty(c.name)})):[])];if(!t.export_columns?.length)t.export_columns=sources;else{t.export_columns=t.export_columns.filter(c=>sources.some(s=>s.source===c.source));for(const source of sources)if(!t.export_columns.some(c=>c.source===source.source))t.export_columns.push(source);}const result=await request('/api/templates',{id:state.templateId,template:t});state.templateId=result.id;state.templateDirty=false;state.template={...t,id:result.id,version:result.version};return result}
async function newTemplate(){if(!await allowDiscard())return;showDialog('Create a template',`<p>Start with a blank template or use the included purchase-order fields as a starting point.</p><label>Template name<input id="new-template-name" placeholder="For example: delivery notes" maxlength="100"></label><label class="check"><input id="use-starter" type="checkbox">Start with purchase-order fields</label><div class="dialog-actions"><button data-close>Cancel</button><button id="create-template" class="primary">Create template</button></div>`);$('#create-template').onclick=()=>{const name=$('#new-template-name').value.trim();if(!name)return toast('Give this template a name.',true);state.template=$('#use-starter').checked?clone(state.data.defaultTemplate):{name,fields:[{name:'document_number',label:'Document number',type:'text',required:true,anchor:'Document number:',position:'after'}],table:{enabled:false,header_anchor:'',end_anchors:[],ignore_prefixes:[],columns:[]},validation:{enabled:false},duplicate_fields:[],export_columns:[]};state.template.name=name;delete state.template.id;state.templateId=null;state.templateDirty=true;state.mode='teach';closeDialog();render()}}
function renderWatches(){const watches=state.data.watches||[];$('#main').innerHTML=`<div class="page"><div class="page-heading"><div><h1>Watch folders</h1><p>Import new documents from folders you choose. Originals stay untouched. Fieldwork checks these folders while the app is running.</p></div><button id="new-watch" class="primary">${icon('plus')}Watch a folder</button></div>${watches.length?`<div class="watch-list">${watches.map(w=>`<article class="watch-row"><div class="watch-row-header"><div><span class="badge ${w.enabled?'':'neutral'}">${w.enabled?'Watching':'Paused'}</span><h2>${esc(w.path)}</h2><p>${esc(state.data.templates.find(t=>t.id===w.templateId)?.name||'Template unavailable')}</p>${w.error?`<p class="inline-error">${esc(w.error)}</p>`:''}${w.lastScanAt?`<p>Last checked ${esc(dateLabel(w.lastScanAt))}</p>`:''}</div><div class="button-row tight"><button data-watch-toggle="${esc(w.id)}">${icon(w.enabled?'pause':'play')}${w.enabled?'Pause':'Resume'}</button><button data-watch-edit="${esc(w.id)}">Edit</button><button data-watch-delete="${esc(w.id)}" class="icon-button quiet" aria-label="Remove watched folder">${icon('trash')}</button></div></div></article>`).join('')}</div>`:`<div class="empty-page">${icon('folder')}<h2>A place for incoming documents.</h2><p>Choose a folder and a template. New PDFs and images will join your document library, ready for review.</p><button id="empty-watch" class="primary">Watch a folder</button></div>`}<p class="hint">Only files directly inside a watched folder are imported. Subfolders and previously imported files are left alone. Pausing or removing a watch never removes documents.</p></div>`;$('#new-watch').onclick=()=>showWatch();$('#empty-watch')?.addEventListener('click',()=>showWatch());$$('[data-watch-edit]').forEach(b=>b.onclick=()=>showWatch(watches.find(w=>w.id===b.dataset.watchEdit)));$$('[data-watch-toggle]').forEach(b=>b.onclick=()=>action(async()=>{const w=watches.find(w=>w.id===b.dataset.watchToggle);await request('/api/watches',{id:w.id,path:w.path,templateId:w.templateId,enabled:!w.enabled});await refresh();toast(w.enabled?'Folder watch paused.':'Folder watch resumed.')}));$$('[data-watch-delete]').forEach(b=>b.onclick=()=>action(async()=>{if(!await confirmAction('Remove this folder watch?','Imported documents and original files will be kept.','Remove watch'))return;await request(`/api/watches/${encodeURIComponent(b.dataset.watchDelete)}`,{},'DELETE');await refresh();toast('Folder watch removed.')}))}
function showWatch(w){showDialog(w?'Edit watched folder':'Watch a folder',`<p>Choose an existing folder on this Mac. Newly discovered PDFs and images will be processed using the selected template.</p><div class="path-row"><label>Folder<input id="watch-path" value="${esc(w?.path||'')}" placeholder="/Users/you/Documents/Incoming" autocomplete="off"></label>${window.webkit?.messageHandlers?.fieldwork?'<button id="choose-watch-folder">Choose folder…</button>':''}</div><label>Template<select id="watch-template">${templateOptions(w?.templateId||state.templateId)}</select></label><label class="check"><input id="watch-enabled" type="checkbox" ${w?.enabled===false?'':'checked'}>Watch for new files</label><p class="hint">Existing files may also be imported when first watched. Nothing is moved or deleted.</p><div class="dialog-actions"><button data-close>Cancel</button><button id="save-watch" class="primary">Save folder watch</button></div>`);$('#choose-watch-folder')?.addEventListener('click',()=>{state.folderTarget='watch-path';window.webkit.messageHandlers.fieldwork.postMessage({action:'chooseWatchFolder'})});$('#save-watch').onclick=()=>action(async()=>{await request('/api/watches',{id:w?.id,path:$('#watch-path').value.trim(),templateId:$('#watch-template').value,enabled:$('#watch-enabled').checked});closeDialog();await refresh();toast('Folder watch saved.')})}
function renderSettings(){const settings=state.data.settings||{};$('#main').innerHTML=`<div class="page settings-layout"><div class="page-heading"><div><h1>Settings</h1><p>Your workspace, stored on this Mac.</p></div></div><section class="settings-section"><h2>Processing</h2><p>${state.data.ocrAvailable?'Local OCR is available for scanned PDFs and supported images. Review scanned text and amounts against the original.':'Local OCR is not available in this runtime. Text PDFs can be processed; scans and images will need review.'}</p><label>Default template<select id="default-template">${templateOptions(settings.defaultTemplateId)}</select></label><div class="button-row"><button id="save-settings">Save default</button></div></section><section class="settings-section"><h2>Backup & restore</h2><p>A workspace backup includes your documents, extracted data, templates and activity. Store the downloaded file somewhere safe. Access keys are excluded.</p><div class="button-row"><a class="button" download href="/api/backup">${icon('download')}Download backup</a><button id="restore-backup">${icon('restore')}Restore backup…</button></div><p class="hint">Restoring replaces this workspace and first saves a recovery snapshot. Finish or cancel running jobs before restoring.</p></section><section class="settings-section"><h2>Agent access</h2><p>Allow a trusted local script or assistant to use Fieldwork’s API. Anyone with this key can access this workspace, so keep it private.</p><div class="button-row"><button id="show-api-key">Show local API key</button><button id="show-api-help">API connection details</button></div></section><section class="settings-section"><h2>Example documents</h2><p>Optional fictional purchase orders help you practice teaching and reviewing without using real business data.</p><button id="settings-samples">Import example documents</button></section><section class="settings-section"><h2>About Fieldwork</h2><p>Version ${esc(state.data.version||'1.0')} · Local document extraction. Files are not sent to an online service. Fieldwork works while open; folder watches stop when you quit.</p><p>Extraction and arithmetic checks assist your review. They cannot establish that a source document is genuine or every value is correct.</p><div class="button-row"><button id="lock-workspace" class="quiet">Lock browser session</button></div></section></div>`;$('#save-settings').onclick=()=>action(async()=>{await request('/api/settings',{defaultTemplateId:$('#default-template').value||null});await refresh();toast('Default template saved.')});$('#restore-backup').onclick=()=>showRestore();$('#show-api-key').onclick=()=>action(async()=>{const r=await request('/api/security/key',{});showDialog('Local API key',`<p>This key grants access to documents and actions in this workspace. Share it only with tools you trust. It is not included in backups.</p><div class="token-box"><input id="revealed-key" value="${esc(r.token)}" readonly aria-label="Local API key" autocomplete="off"><button id="copy-api-key">${icon('copy')}Copy</button></div><div class="dialog-actions"><button data-close>Done</button></div>`);$('#copy-api-key').onclick=()=>copyText(r.token,'API key copied.');});$('#show-api-help').onclick=()=>showDialog('Connect a local tool',`<p>The local API uses a bearer key. Retrieve it through “Show local API key” and store it securely in your tool, not in a document or shared repository.</p><pre>Base URL: ${esc(location.origin)}
Authorization: Bearer YOUR_LOCAL_KEY

GET /api/state
POST /api/upload
POST /api/jobs
POST /api/documents/{id}/review
POST /api/documents/{id}/approve
POST /api/export</pre><p>All source documents stay on this Mac unless the tool you authorize explicitly reads and sends them elsewhere.</p><div class="dialog-actions"><button data-close>Done</button></div>`);$('#settings-samples').onclick=()=>loadExamples();$('#lock-workspace').onclick=()=>action(async()=>{await request('/api/logout',{});clearTimeout(state.jobTimer);state.data=null;renderLogin()})}
function showRestore(){showDialog('Restore a workspace backup',`<p>This replaces the current documents, templates and settings with a previous backup. Fieldwork creates a recovery snapshot first and retains this Mac’s access key.</p><p>Running jobs must finish or be cancelled. Choose a Fieldwork ZIP backup to continue.</p><div class="dialog-actions"><button data-close>Cancel</button><button id="choose-backup" class="primary">Choose backup…</button></div>`);$('#choose-backup').onclick=()=>$('#backup-picker').click()}
async function restoreBackup(file){if(!file)return;showDialog('Restore this backup?',`<p><strong>${esc(file.name)}</strong></p><p>Your current workspace will be replaced. A recovery snapshot is saved first.</p><label>Type RESTORE to continue<input id="restore-confirm" autocomplete="off" spellcheck="false"></label><div class="dialog-actions"><button data-close>Cancel</button><button id="confirm-restore" class="danger">Restore workspace</button></div>`);$('#confirm-restore').onclick=()=>action(async()=>{if($('#restore-confirm').value!=='RESTORE')return toast('Type RESTORE exactly to confirm.',true);const form=new FormData();form.append('backup',file);form.append('confirm','RESTORE');await request('/api/backup/restore',form);state.selected=null;state.checked.clear();state.template=null;state.templateId=null;state.reviewDirty=state.templateDirty=false;closeDialog();await refresh();toast('Workspace restored. Your current access key is unchanged.')})}
function exportSources(docs){const sources=new Map([['source_file',{source:'source_file',label:'Source file'}]]);for(const d of docs){for(const f of fieldDefs(d))sources.set('fields.'+f.name,{source:'fields.'+f.name,label:f.label||pretty(f.name)});for(const c of itemDefs(d))sources.set('items.'+c.name,{source:'items.'+c.name,label:c.label||pretty(c.name)})}sources.set('review_note',{source:'review_note',label:'Review note'});return [...sources.values()]}
function showExport(){if(state.reviewDirty)return toast('Save and check your document changes before exporting.',true);const all=state.data.documents.filter(d=>isApproved(d)&&!d.archived&&d.duplicateDecision!=='ignore');if(!all.length)return toast('Review and approve at least one document before exporting.',true);const selected=all.filter(d=>selection().includes(d.id));let docs=selected.length?selected:all;const sources=exportSources(all);showDialog('Export approved data',`<p>Only approved, unarchived documents are included. Ignored duplicates and unreviewed documents stay out.</p><div class="form-grid"><label>Documents<select id="export-scope"><option value="selected" ${!selected.length?'disabled':''}>Selected approved (${selected.length})</option><option value="all" ${!selected.length?'selected':''}>All approved (${all.length})</option></select></label><label>Format<select id="export-format"><option value="csv">CSV</option><option value="xlsx">Excel workbook</option><option value="json">JSON</option></select></label></div><div id="export-column-heading" class="section-heading"><h3>Columns</h3><small>Rename export headings</small></div><div id="export-columns" class="export-columns">${sources.map((c,i)=>`<div class="export-column"><input type="checkbox" data-export-check="${i}" checked aria-label="Include ${esc(c.label)}"><span>${esc(c.label)}</span><input data-export-label="${i}" value="${esc(c.label)}" aria-label="Export heading for ${esc(c.label)}"></div>`).join('')}</div><p id="export-format-hint" class="hint">CSV and Excel contain one row per line item. Your browser or Mac save dialog chooses where the file is saved.</p><div class="dialog-actions"><button data-close>Cancel</button><button id="download-export" class="primary">${icon('download')}Export file</button></div>`);$('#export-format').onchange=e=>{const json=e.target.value==='json';$('#export-column-heading').classList.toggle('hidden',json);$('#export-columns').classList.toggle('hidden',json);$('#export-format-hint').textContent=json?'JSON keeps the original field names, document structure and review metadata. Your browser or Mac save dialog chooses where the file is saved.':'CSV and Excel contain one row per line item. Your browser or Mac save dialog chooses where the file is saved.'};$('#download-export').onclick=()=>action(async()=>{docs=$('#export-scope').value==='all'?all:selected;const columns=sources.filter((_,i)=>$(`[data-export-check="${i}"]`).checked).map(c=>{const i=sources.indexOf(c);return{source:c.source,label:$(`[data-export-label="${i}"]`).value.trim()||c.label}});const format=$('#export-format').value;if(format!=='json'&&!columns.length)return toast('Select at least one export column.',true);let r;try{r=await request('/api/export',{format,documentIds:docs.map(d=>d.id),...(format==='json'?{}:{columns})},'POST',true)}catch(e){if(e.status===409){closeDialog();await refresh();showBlockedExport(e);return}throw e}await downloadResponse(r,'fieldwork-export.'+format);closeDialog();toast('Approved data exported.')})}
function showBlockedExport(error){const blocked=error.blockedDocuments||[];showDialog('Review before exporting',`<p>${esc(error.message)}</p>${blocked.map(d=>`<div class="issue-panel"><h3>${esc(d.name)}</h3><ul>${(d.issues||[]).map(i=>`<li>${esc(i.message||i)}</li>`).join('')}</ul><button data-review-blocked="${esc(d.id)}">Open document</button></div>`).join('')}<p>No export was downloaded. Review these documents and approve them again before exporting.</p><div class="dialog-actions"><button data-close>Back to workspace</button></div>`);$$('[data-review-blocked]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.reviewBlocked;state.view='documents';state.mode='review';state.page=1;closeDialog();render()})}
async function downloadResponse(response,fallback){const blob=await response.blob();const disposition=response.headers.get('Content-Disposition')||'';const name=disposition.match(/filename\*?=(?:UTF-8''|"?)([^";]+)/i)?.[1]||fallback;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=decodeURIComponent(name);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function showAudit(id){await action(async()=>{const result=await request(`/api/documents/${encodeURIComponent(id)}/audit`);const events=Array.isArray(result)?result:result.events||result.audit||[];showDialog('Document activity',`<p>Changes are recorded locally so you can trace how this document was processed and reviewed.</p>${events.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Action</th><th>When</th></tr></thead><tbody>${events.map(e=>`<tr><td>${esc(pretty(e.action))}</td><td>${esc(dateLabel(e.createdAt||e.created_at))}</td></tr>`).join('')}</tbody></table></div>`:'<p>No activity has been recorded yet.</p>'}<div class="dialog-actions"><button data-close>Done</button></div>`)})}
let dialogResolver=null,previousFocus=null;
function showDialog(title,body){if($('#dialog').open)closeDialog();previousFocus=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;$$('[data-close]',$('#dialog')).forEach(b=>b.onclick=()=>closeDialog(false));$('#dialog').showModal();requestAnimationFrame(()=>$('input:not([type=checkbox]),textarea,select,button.primary',$('#dialog-content'))?.focus())}
function closeDialog(result=false){$('#dialog').close();$('#dialog-content').replaceChildren();previousFocus?.focus?.();if(dialogResolver){const r=dialogResolver;dialogResolver=null;r(result)}}
function confirmAction(title,message,label){return new Promise(resolve=>{showDialog(title,`<p>${esc(message)}</p><div class="dialog-actions"><button data-close>Cancel</button><button id="confirm-action" class="primary">${esc(label)}</button></div>`);dialogResolver=resolve;$('#confirm-action').onclick=()=>closeDialog(true)})}
async function copyText(text,message='Copied.'){try{await navigator.clipboard.writeText(text);toast(message)}catch{toast('Copy is unavailable. Select the text and use Command-C.',true)}}
function showHelp(){showDialog('Working with Fieldwork',`<p>Import a document, teach or choose a template, then review the extracted data beside the original. Approve the documents you want to export.</p><div class="shortcut"><span>Import documents</span><kbd>⌘ / Ctrl + O</kbd></div><div class="shortcut"><span>Search library</span><kbd>⌘ / Ctrl + F</kbd></div><div class="shortcut"><span>Close dialog or source selection</span><kbd>Esc</kbd></div><h3>Check before approving</h3><p>Use “See source” to trace a value, edit fields and rows, then Save & check. Resolve duplicates explicitly. Changes revoke earlier approval.</p><h3>Scanned documents</h3><p>Local OCR reads supported images and scanned PDFs. Uncertain or inconsistent results remain for review. Check names, dates and amounts against the source.</p><h3>When you quit</h3><p>Your documents and templates remain saved. Processing and watched-folder checks resume when Fieldwork opens again.</p><div class="dialog-actions"><button data-close>Done</button></div>`)}
$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#help-button').onclick=showHelp;
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog(false)});
$('#file-picker').onchange=e=>{importFiles(e.target.files);e.target.value=''};
$('#template-picker').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)action(async()=>{if(file.size>1024*1024)throw Error('Choose a template JSON file under 1 MB.');const parsed=JSON.parse(await file.text());const r=await request('/api/templates/import',{template:parsed.template||parsed});state.templateId=r.id;state.template=null;state.view='templates';await refresh();state.templateId=r.id;state.template=clone(state.data.templates.find(t=>t.id===r.id));render();toast('Template imported as a new copy.')})};
$('#backup-picker').onchange=e=>{const file=e.target.files[0];e.target.value='';restoreBackup(file)};
document.addEventListener('click',e=>{const link=e.target.closest('a[download]');if(!link||!link.href.startsWith(location.origin+'/api/'))return;e.preventDefault();action(async()=>{const response=await request(link.getAttribute('href'),undefined,'GET',true);await downloadResponse(response,'fieldwork-download');toast('Download prepared.')})});
let dragDepth=0;document.addEventListener('dragenter',e=>{if(!state.data||!e.dataTransfer.types.includes('Files'))return;e.preventDefault();dragDepth++;$('#upload-overlay').classList.remove('hidden')});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();e.dataTransfer.dropEffect='copy'}});document.addEventListener('dragleave',()=>{dragDepth--;if(dragDepth<=0){dragDepth=0;$('#upload-overlay').classList.add('hidden')}});document.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();dragDepth=0;$('#upload-overlay').classList.add('hidden');if(state.data)importFiles(e.dataTransfer.files)});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='o'){e.preventDefault();if(state.data)$('#file-picker').click()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='f'&&state.view==='documents'){e.preventDefault();$('#document-search')?.focus()}if(e.key==='Escape'&&state.pick){state.pick=null;renderOverlays();renderInspector()}});
window.addEventListener('fieldwork-request-import',()=>{if(state.data)$('#file-picker').click()});window.addEventListener('fieldwork-folder-selected',e=>{const target=state.folderTarget&&document.getElementById(state.folderTarget);if(target&&typeof e.detail?.path==='string')target.value=e.detail.path;state.folderTarget=null});
window.addEventListener('beforeunload',e=>{if(state.reviewDirty||state.templateDirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('focus',()=>{if(state.data&&!state.busy)refresh(false)});
refresh();
